steps.action:
curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { title: { contains: \"Checkout revamp\" } }) { nodes { id identifier title status { name } subIssues { nodes { id identifier title assignee { name email } status { name } } } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { title: { contains: \"Checkout revamp\" } }) { nodes { id identifier title state { name } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(filter: { relations: { type: { eq: \"sub_issue\" }, relatedIssue: { id: { eq: \"i-epic\" } } } }) { nodes { id identifier title assignee { name email } state { name id } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { issues(first: 50) { nodes { id identifier title parent { id title } assignee { name email } state { name id } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "query { workflowStates(filter: { name: { eq: \"Done\" } }) { nodes { id name type } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(id: \"i-9\", stateId: \"t-web-st-4\") { success issue { id identifier title state { name } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(input: { id: \"i-9\", stateId: \"t-web-st-4\" }) { success issue { id identifier title state { name } } } }"
  }'

curl -s https://api.linear.app/graphql \
  -H "Content-Type: application/json" \
  -H "Authorization: Bearer <TOKEN>" \
  -d '{
    "query": "mutation { issueUpdate(id: \"i-9\", input: { stateId: \"t-web-st-4\" }) { success issue { id identifier title state { name } } } }"
  }'
